(* [comment removed for export] *)
Lemma BCALL (pcb : Z) (P : Z -> Prop) (rr t : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model)
      (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) :
  PNRN.mrun_spec RSEGS AD AQ AE L HI pcb 9 (PNRN.margs_begin AD AQ P) PNRN.mprog_push ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 144) ->
  getr R1 (PMK.reg 10) = Z_to_bv 64 op -> getr R1 (PMK.reg 11) = Z_to_bv 64 oa -> getr R1 (PMK.reg 12) = Z_to_bv 64 t ->
  getr R1 (PMK.reg 13) = Z_to_bv 64 oec -> P t ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  RS 1 M1 s1 sm1 e1 cr1 model1 ->
  (forall (fx3 : FPState) (R3 : bvmap 5 word) (M3 : word -> option byte) (model3 : Model) (s3 : PQM.mpst) (st3 : NEM.aest) (sm3 : PM.strm)
          (e3 b3 : bool) (cr3 : credit),
     regs_preserved R1 R3 -> RB M3 s3 st3 sm3 e3 b3 cr3 model3 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 rr M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pcb M1 model1) K.
Proof.
