Fixpoint debits (EB : list (Z * Z)) (cr1 : credit) : credit :=
  match EB with [] => cr1 | b :: EB' => debitR (debits EB' cr1) (snd b) end.
Definition RSxB (EB : list (Z * Z)) (c : Z) (M1 : word -> option byte) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (model1 : Model) : Prop :=
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s1
  /\ ae_at M1 oa ov osk st /\ otx M1 sm1 e1 /\ PQM.mgrow_ok s1
  /\ (e = true -> e1 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1 /\ PM.unread (PQM.p_src s1) sm1 + c <= PM.unread (PQM.p_src s) sm
  /\ PQR.minv_d 0 s1 /\ PQM.p_stk s1 = PQM.p_stk s
  /\ saved M1 /\ cm M1 /\ PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st) /\ model_but_vm model model1
  /\ hi_heap HI (EB ++ PNRN.mown s1 st ++ LBX) (debits EB cr1) M1 (m_vmmaps model1).
Definition RSB (EB : list (Z * Z)) (c : Z) (M1 : word -> option byte) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (model1 : Model) : Prop :=
  RSxB EB c M1 s1 sm1 e1 cr1 model1 /\ NEM.ec_state RSEGS AD M1 oec eb cat.
Lemma RSB_nil c M1 s1 sm1 e1 cr1 model1 : RSB [] c M1 s1 sm1 e1 cr1 model1 <-> RS c M1 s1 sm1 e1 cr1 model1.
