(* [comment removed for export] *)
Definition ATB (pc : Z) (R7 : bvmap 5 word) (M7 : word -> option byte) (s6 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr5 : credit) (model7 : Model)
           (ns fbd p w0 w1 : Z) : Prop :=
  getr R7 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R7 (PMK.reg 8) = Z_to_bv 64 op /\ getr R7 (PMK.reg 9) = Z_to_bv 64 oec
  /\ getr R7 (PMK.reg 18) = Z_to_bv 64 oa /\ getr R7 (PMK.reg 20) = Z_to_bv 64 ns
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R7 (PMK.reg x) = getr R (PMK.reg x))
  /\ 0 <= ns < 2 ^ 32 /\ (pc = 0x4606c -> L5.u8_at RSEGS M7 (sp - 144) 0)
  /\ RSB [(p, 64)] 14 M7 s6 sm5 e5 cr5 model7 /\ PQTST.ws_this_at M7 (sp - 104) (PQTST.WDyn fbd p w0 w1).
Definition DYNB : Prop :=
  forall (pc : Z) (fx7 : FPState) (R7 : bvmap 5 word) (M7 : word -> option byte) (s6 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr5 : credit) (model7 : Model)
         (ns fbd p w0 w1 : Z),
    (pc = 0x461bc \/ pc = 0x4606c) -> ATB pc R7 M7 s6 sm5 e5 cr5 model7 ns fbd p w0 w1 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx7 R7 pc M7 model7) K.

(* [comment removed for export] *)
Lemma hpres_widen LB M M' sp1 scr1 W sp2 scr2 :
  L5C.hpres L LB sp1 scr1 W M M' -> PMFR.brange L LB -> (forall a, PMK.inW W a -> sp2 - scr2 <= a < sp2) ->
  sp2 - scr2 = sp1 - scr1 -> sp1 <= sp2 -> hl_ceil L <= sp1 - scr1 ->
  L5.defined M' (sp2 - scr2) scr2 -> L5C.hpres L LB sp2 scr2 [] M M'.
Proof.
