Lemma PA_tbB EB (M1 M2 : word -> option byte) (s1 : PQM.mpst) (x' : PM.vstr) (cr1 : credit) VM :
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s1 ->
  hi_heap HI (EB ++ PNRN.mown s1 st ++ LBX) cr1 M1 VM -> PQMF.dkr M1 M2 op PQM.PSIZE ->
  (forall a, 0 <= a < 2 ^ 64 -> (op <= a < op + 328 \/ op + 352 <= a < op + 400) -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  (forall B m, In (B, m) (PM.src_own (PQM.p_src s1) ++ PQM.mvec_own (PQM.p_sb s1) (PQM.p_sk s1) ++ PQV8.v8_own (PQM.p_bb s1)) ->
               L5C.agree_on M1 M2 B m) ->
  PM.vstr_at RSEGS PMSP.T3 M2 (op + 328) x' ->
