(* [comment removed for export] *)
Lemma RS_tbWB EB (c : Z) (fx1 fx2 : FPState) (R1 R2 : bvmap 5 word) (pc1 pc2 : Z) (M1 M2 : word -> option byte) (model1 : Model)
      (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (x' : PM.vstr) (lo1 hi1 lo2 hi2 : Z) :
  RSB EB c M1 s1 sm1 e1 cr1 model1 ->
  msteps RSEGS (@mkst fx1 R1 (Z_to_bv 64 pc1) M1 (seg_rom RSEGS)) (@mkst fx2 R2 (Z_to_bv 64 pc2) M2 (seg_rom RSEGS)) -> mem_grows M1 M2 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (lo1 <= i < hi1) -> ~ (lo2 <= i < hi2) -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall a, (lo1 <= a < hi1) \/ (lo2 <= a < hi2) -> (op + 328 <= a < op + 352) \/ (exists B m, In (B, m) (PM.vs_own (PQM.p_tb s1)) /\ B <= a < B + m)) ->
  PM.vstr_at RSEGS PMSP.T3 M2 (op + 328) x' -> PM.vs_own x' = PM.vs_own (PQM.p_tb s1) -> PQM.tb_okM x' ->
  PQM.pot_textM L x' = PQM.pot_textM L (PQM.p_tb s1) ->
  (RSB EB c M2 (PQTSA.with_tb s1 x') sm1 e1 cr1 model1 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M2 model1) K) ->
