(* [comment removed for export] *)
Definition ATW12B (R7 : bvmap 5 word) (M7 : word -> option byte) (s6 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr5 : credit) (model5 : Model)
           (ns fbd p w0 w1 : Z) : Prop :=
  getr R7 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R7 (PMK.reg 8) = Z_to_bv 64 op /\ getr R7 (PMK.reg 9) = Z_to_bv 64 oec
  /\ getr R7 (PMK.reg 18) = Z_to_bv 64 oa /\ getr R7 (PMK.reg 20) = Z_to_bv 64 ns
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R7 (PMK.reg x) = getr R (PMK.reg x))
  /\ getr R7 (PMK.reg 10) = Z_to_bv 64 (sp - 104) /\ getr R7 (PMK.reg 11) = Z_to_bv 64 (op + 328) /\ getr R7 (PMK.reg 1) = Z_to_bv 64 0x461e8
  /\ RSB [(p, 64)] 14 M7 s6 sm5 e5 cr5 model5 /\ PM.vs_size (PQM.p_tb s6) = 0 /\ PQTST.ws_this_at M7 (sp - 104) (PQTST.WDyn fbd p w0 w1)
  /\ (fbd = 1 \/ fbd = 3) /\ 0 <= ns < 2 ^ 32.
(* [comment removed for export] *)
Definition ATD12B (R8 : bvmap 5 word) (M8 : word -> option byte) (s7 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr8 : credit) (model8 : Model) (ns fbd p : Z) : Prop :=
  getr R8 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R8 (PMK.reg 8) = Z_to_bv 64 op /\ getr R8 (PMK.reg 9) = Z_to_bv 64 oec
  /\ getr R8 (PMK.reg 18) = Z_to_bv 64 oa /\ getr R8 (PMK.reg 20) = Z_to_bv 64 ns
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R8 (PMK.reg x) = getr R (PMK.reg x))
  /\ RSB [(p, 64)] 14 M8 s7 sm5 e5 cr8 model8 /\ 1 <= PM.vs_size (PQM.p_tb s7) <= 31 /\ L5.u8_at RSEGS M8 (sp - 104) fbd /\ (fbd = 1 \/ fbd = 3)
  /\ L5.u64_at RSEGS M8 (sp - 88) 8 /\ L5.u64_at RSEGS M8 (sp - 80) p /\ 0 <= ns < 2 ^ 32
  /\ PQTSS.ts_text M8 (op + 328) (PQM.p_tb s7).

(* [comment removed for export] *)
Lemma TS12_UTB (pc : Z) (fx6 : FPState) (R6 : bvmap 5 word) (M6 : word -> option byte) (s5 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr5 : credit)
      (model5 : Model) (ns fbd p w0 w1 : Z) :
  (pc = 0x461bc \/ pc = 0x4606c) ->
  ATB pc R6 M6 s5 sm5 e5 cr5 model5 ns fbd p w0 w1 ->
  (forall (fx7 : FPState) (R7 : bvmap 5 word) (M7 : word -> option byte),
      msteps RSEGS (@mkst fx6 R6 (Z_to_bv 64 pc) M6 (seg_rom RSEGS)) (@mkst fx7 R7 (Z_to_bv 64 0x46c40) M7 (seg_rom RSEGS)) ->
      ATW12B R7 M7 (PQTSA.with_tb s5 (PQTSA.vs_clear (PQM.p_tb s5))) sm5 e5 cr5 model5 ns fbd p w0 w1 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx7 R7 0x46c40 M7 model5) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 pc M6 model5) K.
