Lemma VCALLXB (p : Z) (pcv : Z) (args : bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
      (pre : bvmap 5 word -> (word -> option byte) -> NEM.aest -> Prop) (step : bvmap 5 word -> (word -> option byte) -> NEM.aest -> NEM.aest -> bool -> bool -> Prop)
      (rr : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool)
      (cr1 : credit) (c : Z) :
  PNV.vis_spec RSEGS AD AQ AE L HI pcv args pre step ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 144) -> getr R1 (PMK.reg 10) = Z_to_bv 64 oa ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  args R1 M1 (sp - 144) oa oec (PQM.mparser_own s1 ++ (p, 64) :: LBX) -> pre R1 M1 st ->
  (forall st' (bb bb' : bool), step R1 M1 st st' bb bb' ->
     NEM.nlv st' = NEM.nlv st /\ NEM.kbsize st' <= NEM.kbsize st + 7 * c /\ NEM.phi st' <= NEM.phi st + 8 * c /\ NEM.esize st' = NEM.esize st /\ NEM.edepth st' = NEM.edepth st) ->
  0 <= c -> RSB [(p, 64)] c M1 s1 sm1 e1 cr1 model1 ->
  (forall (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (model2 : Model) (st2 : NEM.aest) (e2 b2 : bool) (cr2 : credit),
     regs_preserved R1 R2 -> RVB p c M2 s1 st2 sm1 e2 b2 cr2 model2 ->
     (forall a m, sp - 144 <= a -> a + m <= sp -> L5C.agree_on M1 M2 a m) ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 rr M2 model2) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pcv M1 model1) K.
Proof.
