Module PQTSG.
Import PMS.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Local Ltac lia := L5FastLia.plia.
Local Ltac splits H := lazymatch type of H with _ /\ _ => let H1 := fresh "Cj" in let H2 := fresh "Cj" in destruct H as [H1 H2]; splits H1; splits H2 | _ => idtac end.

(* [comment removed for export] *)
Lemma fill_run0 (fx : FPState) R M (dst n r : Z) :
  getr R (reg 10) = Z_to_bv 64 dst -> getr R (reg 11) = Z_to_bv 64 0 -> getr R (reg 12) = Z_to_bv 64 n ->
  getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r ->
  0 <= n -> 0 <= dst -> dst + n < 2 ^ 63 -> L5.writable RSEGS M dst n ->
  exists R3 M3, msteps RSEGS (@mkst fx R (Z_to_bv 64 0xb9ef8) M (seg_rom RSEGS)) (@mkst fx R3 (Z_to_bv 64 r) M3 (seg_rom RSEGS))
    /\ mem_grows M M3
    /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (dst <= a < dst + n) -> M3 (Z_to_bv 64 a) = M (Z_to_bv 64 a))
    /\ PM.zeros_at M3 dst n
