Lemma grow_post_of M' fbd p w0 w1 :
  mem_ok M' -> L5.u8_at RSEGS M' o fbd -> (fbd = 1 \/ fbd = 3) -> L5.u64_at RSEGS M' (o + 8) 2 -> L5.u64_at RSEGS M' (o + 16) 8 -> L5.u64_at RSEGS M' (o + 24) p ->
  L5.u64_at RSEGS M' p w0 -> L5.u64_at RSEGS M' (p + 8) w1 -> 0 <= w0 < 2 ^ 64 -> 1 <= w1 <= 2 ^ 62 + 1 ->
  L5C.fresh_block L LB M' p 64 -> p mod 16 = 0 -> 4096 <= p -> p + 64 <= hl_ceil L ->
  PQTST.grow_post L LB M0 M' sp o fbd p w0 w1.
