Lemma add_main (fx0 : FPState) (y r v0 v1 : Z) :
  getr R0 (reg 10) = Z_to_bv 64 o -> getr R0 (reg 11) = Z_to_bv 64 y -> 0 <= y < 2 ^ 64 ->
  getr R0 (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R0 (reg 2) = Z_to_bv 64 sp ->
  PQTSS.binl_at M0 o 0 2 v0 v1 -> 1 <= v1 <= 2 ^ 62 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (p w0 w1 : Z),
      regs_preserved R0 R' -> getr R' (reg 10) = Z_to_bv 64 o ->
      PQTST.grow_post L LB M0 M' sp o 1 p w0 w1 -> w0 + 2 ^ 64 * w1 = v0 + 2 ^ 64 * v1 + PQTST.lo32 y ->
      model_but_vm model0 model' -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx0 R0 PQTST.ADDU32 M0 model0) K.
Proof.
