(* [comment removed for export] *)
Lemma sub_main (fx0 : FPState) (t r v0 v1 nv : Z) (lt : nat) :
  getr R0 (reg 10) = Z_to_bv 64 o -> getr R0 (reg 11) = Z_to_bv 64 t ->
  getr R0 (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R0 (reg 2) = Z_to_bv 64 sp ->
  PQTSS.binl_at M0 o 2 2 v0 v1 -> 1 <= v1 <= 2 ^ 62 ->
  PQTSS.binl_at M0 t 0 lt nv 0 -> (lt <= 1)%nat -> 0 <= nv < 2 ^ 32 ->
  t mod 8 = 0 -> sp <= t -> t + 32 <= hl_sptop L -> (o + 32 <= t \/ t + 32 <= o) -> L5.defined M0 t 32 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (p w0 w1 : Z),
      regs_preserved R0 R' -> getr R' (reg 10) = Z_to_bv 64 o ->
      PQTST.grow_post L LB M0 M' sp o 3 p w0 w1 -> w0 + 2 ^ 64 * w1 = v0 + 2 ^ 64 * v1 + (match lt with 1%nat => nv | _ => 0 end) ->
      model_but_vm model0 model' -> hi_heap HI ((p, 64) :: LB) (debitR cr0 64) M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx0 R0 PQTST.SUBB M0 model0) K.
Proof.
