Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQTSTOP.
Import PMS. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Abbreviation AQ := PnLayoutQS.QADDR_S.
Abbreviation AE := NemLayoutS.NEADDR_S.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.

(* [comment removed for export] *)
Lemma ws_all : PQTSS.ws1_spec L HI -> PQTST.ws2i_spec L HI -> PQTST.ws2d_spec L HI -> PQTST.ws_spec L HI.
Proof. intros W1 W2I W2D. exact (PQTST.ws_spec_join L HI (PQTST.ws_inl1_of_ws1 L HI W1) W2I W2D). Qed.

(* [comment removed for export] *)
Theorem TS8_w9 :
  PQTSS.mulu_run_stmt -> PQTSS.add64_run_stmt -> PQTSS.ws1_spec L HI -> PNV.v_string_spec RSEGS AD AQ AE L HI ->
  PQMRI.w9_family L HI (PQRIE.TS8 L HI).
Proof.
  intros MUL ADD WS1 VS R M0 model K LBX cr sp r fb cat n s st str sm e eb PRE KONT.
  exact (PQTSA.TS8_ok L HI LY HIok R M0 model K LBX cr sp r fb cat n s st str sm e eb PRE KONT MUL ADD WS1 VS).
Qed.

(* [comment removed for export] *)
Theorem TS12_w9 :
  PMSR.opnewR_spec RSEGS AD L HI -> PMSR.opdelR_spec RSEGS AD L HI ->
  PQTSS.ws1_spec L HI -> PQTST.ws2i_spec L HI -> PQTST.ws2d_spec L HI ->
  PGS.src_read_specG RSEGS AD L HI -> PQR.make_ec_spec RSEGS AD AQ L HI -> PNV.v_string_spec RSEGS AD AQ AE L HI ->
  PQMRI.w9_family L HI (PQRIE.TS12 L HI).
Proof.
  intros OPN OPD W1 W2I W2D SRD MKEC VS R M0 model K LBX cr sp r fb cat n s st str sm e eb PRE KONT.
  pose proof (ws_all W1 W2I W2D) as WS.
  exact (PQTSB.TS12_ok L HI LY HIok R M0 model K LBX cr sp r fb cat n s st str sm e eb PRE KONT
           PQTSAR.mulu_ok PQTSAR2.addns_ok PQTSAR2.subns_ok (PQTSG.addns2_ok L HI LY HIok OPN) (PQTSG.subns2_ok L HI LY HIok OPN)
           WS SRD MKEC VS (PQTSD.DYN12_ok L HI LY HIok R M0 model K LBX cr sp r fb cat n s st str sm e eb PRE KONT W2D VS OPD)).
Qed.

End WithHeap.
End PQTSTOP.

